package com.interview;
import com.sun.net.httpserver.*;import java.net.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;
public class LocalServer {
 public static void main(String[]args)throws Exception{App app=new App();int port=Integer.parseInt(System.getenv().getOrDefault("PORT","8080"));HttpServer server=HttpServer.create(new InetSocketAddress(System.getenv().getOrDefault("HOST","127.0.0.1"),port),0);server.setExecutor(Executors.newFixedThreadPool(12));Path root=Path.of("src/main/webapp").toAbsolutePath();server.createContext("/",x->{try{var h=x.getResponseHeaders();h.set("X-Content-Type-Options","nosniff");h.set("Referrer-Policy","same-origin");h.set("Content-Security-Policy","default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'");h.set("Cache-Control","no-store");byte[]out;int status=200;String path=x.getRequestURI().getPath();if(path.startsWith("/api/")){byte[]data=x.getRequestBody().readNBytes(20001);if(data.length>20000){status=413;out="{\"error\":\"Request too large\"}".getBytes();}else{var q=x.getRequestHeaders();App.Reply r=app.request(x.getRequestMethod(),path.substring(4),new String(data,StandardCharsets.UTF_8),q.getFirst("Cookie")==null?"":q.getFirst("Cookie"),q.getFirst("Origin"),q.getFirst("Host"),false,x.getRemoteAddress().getAddress().getHostAddress());status=r.status();out=Json.write(r.body()).getBytes(StandardCharsets.UTF_8);if(r.cookie()!=null)h.set("Set-Cookie",r.cookie());}h.set("Content-Type","application/json; charset=utf-8");}else{Path f=root.resolve(path.equals("/")?"index.html":path.substring(1)).normalize();if(!x.getRequestMethod().equals("GET")||!f.startsWith(root)||!Files.isRegularFile(f)){status=404;out="Not found".getBytes();}else{out=Files.readAllBytes(f);String type=path.endsWith(".css")?"text/css":path.endsWith(".js")?"text/javascript":path.endsWith(".svg")?"image/svg+xml":"text/html";h.set("Content-Type",type+"; charset=utf-8");}}x.sendResponseHeaders(status,out.length);x.getResponseBody().write(out);}finally{x.close();}});server.start();System.out.println("Interview Studio: http://localhost:"+port+" (Ctrl+C to stop)");}
}
